+	[
+		"mkdirp",
+		(fs, p) =>
+			new Promise((resolve, reject) => {
+				mkdirp(
+					/** @type {OutputFileSystem} */ (/** @type {unknown} */ (fs)),
+					p,
+					(err) => {
+						if (err) reject(err);
+						else resolve();
+					}
+				);
+			})
+	],
+	[
+		"mkdirpSync",
+		async (fs, p) => {
+			mkdirpSync(
+				/** @type {IntermediateFileSystem} */ (/** @type {unknown} */ (fs)),
+				p
